const input = $input.first().json;
const scenarioId = String(input.scenario_id ?? '').trim();
const memberId = String(input.member_id ?? '').trim();
const debugTraceEnabled = ['1', 'true', 'yes', 'on'].includes(String($env.ONECALL_DEBUG_TRACE ?? 'false').trim().toLowerCase());
const state = {
  case_id: 'CASE-' + (scenarioId || 'UNKNOWN') + '-' + (memberId || 'UNKNOWN'),
  scenario_id: scenarioId,
  member_id: memberId,
  member_inquiry: String(input.member_inquiry ?? ''),
  service_code: String(input.service_code ?? '').trim() || null,
  service_date: String(input.service_date ?? '').trim() || null,
  plan_id: null,
  workflow_status: 'INVESTIGATING',
  iteration: 0,
  max_iterations: 8,
  eligibility: null,
  benefits: null,
  claim: null,
  authorization: null,
  provider: null,
  agents_called: [],
  tool_calls: [],
  tool_errors: [],
  authorization_attempt_count: 0,
  authorization_alternate_used: false,
  root_cause: null,
  recommended_action: null,
  member_transfer_required: 'UNKNOWN',
  human_approval_required: false,
  human_handoff_reason: null,
  final_resolution: null,
  debug_trace_enabled: debugTraceEnabled,
  debug_trace: []
};
const addTrace = (state, component, event, status, details = {}) => {
  if (!state.debug_trace_enabled) return;
  if (!Array.isArray(state.debug_trace)) state.debug_trace = [];
  const normalizedStatus = status === 'SUCCESS' ? 'OK' : status === 'STARTED' ? 'START' : status === 'FAILURE' ? 'ERROR' : status;
  state.debug_trace.push({
    seq: state.debug_trace.length + 1,
    timestamp: new Date().toISOString(),
    component,
    event,
    status: normalizedStatus,
    iteration: Number(state.iteration ?? 0),
    details
  });
};
addTrace(state, 'MAIN', 'CASE_INITIALIZED', 'OK', {
  scenario_id: state.scenario_id,
  member_id: state.member_id,
  service_code: state.service_code,
  service_date: state.service_date,
  max_iterations: state.max_iterations
});
return [{ json: { case_state: state } }];

const state = JSON.parse(JSON.stringify($json.case_state));
const addTrace = (state, component, event, status, details = {}) => {
