  });
};
state.iteration = Number(state.iteration ?? 0) + 1;
addTrace(state, 'MAIN', 'ITERATION_STARTED', 'START', {
  iteration: state.iteration,
  workflow_status: state.workflow_status
});
addTrace(state, 'MAIN', 'ORCHESTRATOR_CALL_START', 'START', {
  iteration: state.iteration,
  has_eligibility: Boolean(state.eligibility),
  has_benefits: Boolean(state.benefits),
  has_claim: Boolean(state.claim),
  has_authorization: Boolean(state.authorization),
  has_provider: Boolean(state.provider)
});
const guardExceeded = state.iteration > 8;
if (guardExceeded) {
  state.workflow_status = 'HUMAN_ESCALATION';
  state.human_approval_required = true;
  state.human_handoff_reason = 'Maximum orchestration iterations exceeded.';
  addTrace(state, 'MAIN', 'MAX_ITERATION_REACHED', 'ERROR', {
    max_iterations: Number(state.max_iterations ?? 8)
  });
}
return [{ json: { case_state: state, guard_exceeded: guardExceeded } }];

