const state = JSON.parse(JSON.stringify($('Iteration Guard').item.json.case_state));
const response = $input.first().json;
const addTrace = (state, component, event, status, details = {}) => {
  if (!state.debug_trace_enabled) return;
  if (!Array.isArray(state.debug_trace)) state.debug_trace = [];
  const normalizedStatus = status === 'SUCCESS' ? 'OK' : status === 'STARTED' ? 'START' : status === 'FAILURE' ? 'ERROR' : status;
  state.debug_trace.push({
    seq: state.debug_trace.length + 1,
    timestamp: new Date().toISOString(),
    component,
    event,
    status: normalizedStatus,
    iteration: Number(state.iteration ?? 0),
    details
  });
};
if (state.debug_trace_enabled && Array.isArray(response.debug_trace)) {
  state.debug_trace = JSON.parse(JSON.stringify(response.debug_trace));
}
state.agents_called.push('ORCHESTRATOR');
let decision = response.decision;
let reason = response.reason;
addTrace(state, 'ORCHESTRATOR', 'ORCHESTRATOR_DECISION_RECEIVED', response.status === 'SUCCESS' ? 'SUCCESS' : 'ERROR', {
  decision: typeof response.decision === 'string' ? response.decision : null,
  status: typeof response.status === 'string' ? response.status : null,
  reason: typeof response.reason === 'string' ? response.reason : null,
  required_input_keys: response.required_inputs && typeof response.required_inputs === 'object' ? Object.keys(response.required_inputs).sort() : []
});
if (response.status !== 'SUCCESS') {
  decision = 'HUMAN_ESCALATION';
  reason = response.reason || 'Orchestrator agent output was invalid.';
  state.tool_errors.push({ tool: 'ORCHESTRATOR', attempt: state.iteration, error: response.error || reason });
}
state.last_orchestrator_decision = { decision, reason, iteration: state.iteration };
addTrace(state, 'ROUTER', 'ROUTE_SELECTED', response.status === 'SUCCESS' ? 'OK' : 'ERROR', { decision, target: decision });
return [{ json: { case_state: state, decision, reason, required_inputs: response.required_inputs || {} } }];

