      : 'AUTH_ALTERNATE_SELECTED';
  addTrace(state, 'AUTHORIZATION', recoveryEvent, authorization_route === 'ALTERNATE_REQUIRED' ? 'OK' : 'START', {
    authorization_route,
    prior_attempt_count: Number(state.authorization_attempt_count ?? 0)
